//! Build, lint and test pipeline for temporal-dsql, including the DSQL plugin's live
//! tests on throwaway AWS resources.
//!
//! Every function runs inside the Dagger engine, so the same calls work from a
//! laptop, a CI agent or a managed engine. Orchestration, secrets and engine
//! provisioning stay outside the module.

// Dagger functions take their options as arguments.
#![allow(clippy::too_many_arguments)]

// Generated by `dagger generate`; regenerate after changing exported items.
pub mod dagger_generated;

use std::time::{SystemTime, UNIX_EPOCH};

use dagger_generated::ModuleContext;
use dagger_sdk::{Container, Directory, File, ModuleError, Secret};

const BUILD_TAGS: &str = "disable_grpc_modules";
const TEST_TAGS: &str = "disable_grpc_modules,test_dep";
const GOLANGCI_LINT: &str = "github.com/golangci/golangci-lint/v2/cmd/golangci-lint@v2.9.0";
const ERRORTYPE: &str = "fillmore-labs.com/errortype@v0.0.7";
const BINARIES: [(&str, &str); 3] = [
    ("temporal-server", "./cmd/server"),
    ("temporal-dsql-tool", "./cmd/tools/dsql"),
    ("temporal-elasticsearch-tool", "./cmd/tools/elasticsearch"),
];
/// Creates the throwaway cluster and table, runs the live tests, and deletes both.
const LIVE_SCRIPT: &str = include_str!("live.sh");
const WEB_IDENTITY_TOKEN: &str = "/run/secrets/aws-web-identity-token";

#[dagger_sdk::object(root, rename = "Ci")]
pub struct Ci {
    #[dagger(state)]
    source: Directory,
}

#[dagger_sdk::methods]
impl Ci {
    #[dagger(constructor, rename = "ci")]
    pub fn new(
        #[dagger(
            doc = "Repository checkout; defaults to the workspace root.",
            default_path = "/",
            ignore = [
                ".git", ".claude", ".cursor", ".idea", ".vscode", ".dagger", ".buildkite",
                "**/.DS_Store", ".bin", ".stamp", ".tmp", ".testoutput", ".coverage", "dist",
                "develop/docker-compose", "temporal-*", "tdbg", "tctl*", "fairsim", "poolsim"
            ]
        )]
        source: Directory,
    ) -> Ci {
        Ci { source }
    }

    /// Compiles temporal-server, temporal-dsql-tool and temporal-elasticsearch-tool.
    #[dagger(function)]
    pub async fn build(
        &self,
        #[dagger(context)] ctx: ModuleContext,
        #[dagger(doc = "Target platform, such as linux/arm64; defaults to the engine's platform.")]
        platform: Option<String>,
    ) -> Result<Directory, ModuleError> {
        let platform = resolve_platform(&ctx, platform).await?;
        self.binaries(&ctx, &platform).await
    }

    /// Runs golangci-lint and the errortype vet check, as make lint-code does.
    #[dagger(function)]
    pub async fn lint(
        &self,
        #[dagger(context)] ctx: ModuleContext,
        #[dagger(
            doc = "Unified diff that limits golangci-lint to the lines it changes; lints everything when omitted."
        )]
        patch: Option<File>,
    ) -> Result<String, ModuleError> {
        let query = ctx.query();
        let mut golangci = vec![
            "golangci-lint",
            "run",
            "--build-tags",
            TEST_TAGS,
            "--timeout",
            "30m",
            "--fix=false",
            "--config=.github/.golangci.yml",
        ];
        let mut linter = self
            .go_builder(&ctx)
            .await?
            .with_mounted_cache(
                query.cache_volume("temporal-dsql-golangci-lint"),
                "/root/.cache/golangci-lint",
            )
            .with_exec(vec!["go", "install", GOLANGCI_LINT])
            .with_exec(vec!["go", "install", ERRORTYPE]);
        if let Some(patch) = patch {
            linter = linter.with_file("/tmp/lint.patch", patch);
            golangci.push("--new-from-patch=/tmp/lint.patch");
        }
        let linted = linter.with_exec(golangci);
        let issues = linted.stdout().await?;
        let vetted = linted
            .with_exec(vec![
                "go",
                "vet",
                "-tags",
                TEST_TAGS,
                "-vettool=/go/bin/errortype",
                "-style-check=false",
                "./...",
            ])
            .stdout()
            .await?;
        Ok(format!("{issues}{vetted}"))
    }

    /// Runs the SQL persistence, DSQL plugin, schema, DSQL tool and pool simulator tests
    /// with the race detector.
    #[dagger(function)]
    pub async fn test(
        &self,
        #[dagger(context)] ctx: ModuleContext,
        #[dagger(doc = "Package patterns to test instead of the default set.")] packages: Option<
            Vec<String>,
        >,
        #[dagger(doc = "Only run tests matching this regular expression, as go test -run.")]
        run: Option<String>,
    ) -> Result<String, ModuleError> {
        let mut args = strings(&[
            "go",
            "test",
            "-race",
            "-shuffle=on",
            "-timeout=35m",
            "-tags",
            TEST_TAGS,
        ]);
        if let Some(run) = run {
            args.extend(["-run".to_owned(), run]);
        }
        args.extend(packages.unwrap_or_else(|| {
            strings(&[
                "./common/persistence/sql/...",
                "./schema/...",
                "./tools/dsql/...",
                "./tools/poolsim/...",
            ])
        }));
        Ok(self
            .go_builder(&ctx)
            .await?
            .with_env_variable("CGO_ENABLED", "1")
            .with_exec(args)
            .stdout()
            .await?)
    }

    /// Runs the DSQL plugin's live tests on a throwaway Aurora DSQL cluster and DynamoDB
    /// table, and deletes both however the run ends. Pass a role and a web identity token,
    /// as CI does, or an access key.
    #[dagger(function, cache = "never")]
    pub async fn live(
        &self,
        #[dagger(context)] ctx: ModuleContext,
        #[dagger(doc = "Region for the throwaway resources.", default = "eu-west-1")]
        region: String,
        #[dagger(
            doc = "ARN of the role to assume with the web identity token; a secret, so logs don't show the account."
        )]
        role_arn: Option<Secret>,
        #[dagger(doc = "Web identity token for the role, such as a Buildkite OIDC token.")]
        web_identity_token: Option<Secret>,
        #[dagger(doc = "Access key ID, when no role is given.")] aws_access_key_id: Option<Secret>,
        #[dagger(doc = "Secret access key, when no role is given.")] aws_secret_access_key: Option<
            Secret,
        >,
        #[dagger(doc = "Session token, for a temporary access key.")] aws_session_token: Option<
            Secret,
        >,
    ) -> Result<String, ModuleError> {
        // A run ID of its own on every call names the run's resources, and keeps the
        // engine from reusing an earlier run's results.
        let run = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|err| ModuleError::new(err.to_string()))?
            .as_millis()
            .to_string();
        let runner = self
            .go_builder(&ctx)
            .await?
            .with_exec(vec!["apk", "add", "--no-cache", "aws-cli", "bash"])
            .with_env_variable("AWS_REGION", region)
            .with_env_variable("CI_RUN", run);
        let runner = match (role_arn, web_identity_token) {
            (Some(role), Some(token)) => runner
                .with_mounted_secret(WEB_IDENTITY_TOKEN, token)
                .with_env_variable("AWS_WEB_IDENTITY_TOKEN_FILE", WEB_IDENTITY_TOKEN)
                .with_secret_variable("AWS_ROLE_ARN", role)
                .with_env_variable("AWS_ROLE_SESSION_NAME", "temporal-dsql-ci"),
            (None, None) => {
                let (Some(id), Some(key)) = (aws_access_key_id, aws_secret_access_key) else {
                    return Err(ModuleError::new(
                        "pass --role-arn with --web-identity-token, or --aws-access-key-id with --aws-secret-access-key",
                    ));
                };
                let runner = runner
                    .with_secret_variable("AWS_ACCESS_KEY_ID", id)
                    .with_secret_variable("AWS_SECRET_ACCESS_KEY", key);
                match aws_session_token {
                    Some(token) => runner.with_secret_variable("AWS_SESSION_TOKEN", token),
                    None => runner,
                }
            }
            _ => {
                return Err(ModuleError::new(
                    "--role-arn and --web-identity-token go together",
                ));
            }
        };
        Ok(runner
            .with_new_file(LIVE_SCRIPT, "/ci/live.sh")
            .with_exec(vec!["bash", "/ci/live.sh"])
            .stdout()
            .await?)
    }
}

impl Ci {
    /// Go toolchain matching go.mod, with module and build caches and the source at /src.
    async fn go_builder(&self, ctx: &ModuleContext) -> Result<Container, ModuleError> {
        let go = go_version(&self.source).await?;
        let query = ctx.query();
        Ok(query
            .container()
            .from(format!("golang:{go}-alpine"))
            .with_exec(vec![
                "apk",
                "add",
                "--no-cache",
                "make",
                "git",
                "gcc",
                "musl-dev",
            ])
            .with_mounted_cache(query.cache_volume("temporal-dsql-go-mod"), "/go/pkg/mod")
            .with_mounted_cache(
                query.cache_volume(format!("temporal-dsql-go-build-{go}")),
                "/root/.cache/go-build",
            )
            .with_directory("/src", self.source.clone())
            .with_workdir("/src"))
    }

    /// Cross-compiles the binaries on the engine's own platform.
    async fn binaries(
        &self,
        ctx: &ModuleContext,
        platform: &str,
    ) -> Result<Directory, ModuleError> {
        let (os, arch) = split_platform(platform)?;
        let mut builder = self
            .go_builder(ctx)
            .await?
            .with_env_variable("CGO_ENABLED", "0")
            .with_env_variable("GOOS", os)
            .with_env_variable("GOARCH", arch);
        for (binary, package) in BINARIES {
            builder = builder.with_exec(vec![
                "go".to_owned(),
                "build".to_owned(),
                "-tags".to_owned(),
                BUILD_TAGS.to_owned(),
                "-o".to_owned(),
                format!("/out/{binary}"),
                package.to_owned(),
            ]);
        }
        Ok(builder.directory("/out"))
    }
}

fn strings(values: &[&str]) -> Vec<String> {
    values.iter().map(|value| (*value).to_owned()).collect()
}

/// Reads the language version from go.mod and returns its major.minor, the tag
/// granularity of the official golang images.
async fn go_version(source: &Directory) -> Result<String, ModuleError> {
    let go_mod = source.file("go.mod").contents().await?;
    let version = go_mod
        .lines()
        .find_map(|line| line.strip_prefix("go "))
        .ok_or_else(|| ModuleError::new("go.mod has no go directive"))?
        .trim();
    let mut parts = version.split('.');
    match (parts.next(), parts.next()) {
        (Some(major), Some(minor)) => Ok(format!("{major}.{minor}")),
        _ => Err(ModuleError::new(format!(
            "unexpected go directive: {version}"
        ))),
    }
}

async fn resolve_platform(
    ctx: &ModuleContext,
    platform: Option<String>,
) -> Result<String, ModuleError> {
    match platform {
        Some(platform) => Ok(platform),
        None => Ok(ctx.query().default_platform().await?.into_inner()),
    }
}

/// Splits os/arch[/variant] into the GOOS and GOARCH values.
fn split_platform(platform: &str) -> Result<(String, String), ModuleError> {
    let mut parts = platform.split('/');
    match (parts.next(), parts.next()) {
        (Some(os), Some(arch)) if !os.is_empty() && !arch.is_empty() => {
            Ok((os.to_owned(), arch.to_owned()))
        }
        _ => Err(ModuleError::new(format!(
            "platform must look like linux/amd64, got {platform}"
        ))),
    }
}
